"use client"

import React, { useCallback, useEffect, useRef, useState } from "react"
import { SparkleIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useSmViewpoint } from "@/hooks/reuseables/useSmViewpoint"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Button } from "@/components/atoms/buttons/Button"
import { useContentAiChatOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useContentAiChatModeStore } from "@/hooks/zustand/contentAiChatMode/store"
import { FloatingActionButton } from "@/components/composites/buttons/FloatingActionButton"

/** localStorage key for the FAB's persisted vertical position (px from viewport bottom). */
const STORAGE_KEY = "contentAiFabBottom"
/** Default distance from the viewport bottom (px). */
const DEFAULT_BOTTOM = 96
/** Lowest the FAB may sit (px from bottom) — keeps it clear of the very edge. */
const MIN_BOTTOM = 16
/** Pixels the pointer must travel before a press counts as a drag (not a click). */
const DRAG_THRESHOLD = 6
/** Headroom kept below the top edge so the FAB never drags off-screen (px). */
const TOP_GUARD = 80

/** Props for {@link ContentAiFab}. */
export interface ContentAiFabProps {
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * Floating "ask StarCi AI" button — the TRIGGER for the app-wide chat, mounted
 * ONCE by `InnerLayout` so it is reachable from EVERY route, not just a course's
 * learn surface: with a lesson open it grounds on that lesson, with a course but
 * no lesson it grounds on the course, and with no course at all (e.g. the
 * dashboard) it opens a `global`, anchorless conversation — see the scope ladder
 * in {@link import("@/components/blocks/learn/ContentAiChat").ContentAiChat}.
 * The panel is presented per the learner's persisted choice
 * ({@link useContentAiChatModeStore}), switchable in the panel header:
 * - **rail** — a resizable right-edge side panel that reflows the app column
 *   (see `InnerLayout`'s split); the FAB here is only the draggable toggle,
 *   hidden while the rail is open (the rail carries its close).
 * - **drawer** — the slide-in {@link import("@/components/overlays/drawers/ContentAiChatDrawer").ContentAiChatDrawer}
 *   (rendered globally); the FAB is its trigger.
 *
 * MOBILE always uses the drawer regardless of the preference. Open-state lives in
 * the shared overlay store (`contentAiChat` key).
 *
 * @param props - {@link ContentAiFabProps}
 */
export const ContentAiFab = ({ classNames }: ContentAiFabProps) => {
    const t = useTranslations()
    const { isOpen, setOpen, open } = useContentAiChatOverlayState()
    const { mode } = useContentAiChatModeStore()
    const { isMobile } = useSmViewpoint()
    // a phone is always the drawer — a side rail is too cramped there.
    const effectiveMode = isMobile ? "drawer" : mode

    // vertical position of the FAB (px from viewport bottom); restored from localStorage on mount
    const [bottom, setBottom] = useState<number>(DEFAULT_BOTTOM)
    useEffect(() => {
        // localStorage is client-only; read once after mount to seed the persisted position
        const saved = window.localStorage.getItem(STORAGE_KEY)
        if (saved !== null && !Number.isNaN(Number(saved))) {
            setBottom(Number(saved))
        }
    }, [])

    // drag bookkeeping: a press opens the panel ONLY when it did not become a drag
    const draggingRef = useRef(false)
    const startRef = useRef<{ pointerY: number; bottom: number } | null>(null)

    // remember where the drag began so we can offset from it
    const onPointerDown = useCallback(
        (event: React.PointerEvent) => {
            startRef.current = { pointerY: event.clientY, bottom }
            draggingRef.current = false
            event.currentTarget.setPointerCapture?.(event.pointerId)
        },
        [bottom],
    )

    // move the FAB up/down with the pointer, clamped to the viewport; mark it a drag past the threshold
    const onPointerMove = useCallback((event: React.PointerEvent) => {
        const start = startRef.current
        if (!start) {
            return
        }
        // dragging UP (smaller clientY) should RAISE the bubble → larger `bottom`
        const delta = start.pointerY - event.clientY
        if (Math.abs(delta) > DRAG_THRESHOLD) {
            draggingRef.current = true
        }
        const maxBottom = window.innerHeight - TOP_GUARD
        setBottom(Math.min(Math.max(start.bottom + delta, MIN_BOTTOM), maxBottom))
    }, [])

    // end the gesture; persist the new position only if it was actually a drag
    const onPointerUp = useCallback(
        (event: React.PointerEvent) => {
            if (startRef.current && draggingRef.current) {
                window.localStorage.setItem(STORAGE_KEY, String(bottom))
            }
            startRef.current = null
            event.currentTarget.releasePointerCapture?.(event.pointerId)
        },
        [bottom],
    )

    // a real press (not a drag) opens the panel; swallow the click that fires at the
    // end of a drag-release.
    const onOpen = useCallback(() => {
        if (draggingRef.current) {
            draggingRef.current = false
            return
        }
        setOpen(true)
    }, [setOpen])

    // No course-required gate any more: with no course at all (dashboard,
    // profile, …) the chat just opens `global`-scoped instead of hiding itself —
    // see the scope ladder in `ContentAiChat`.

    // DRAWER — the panel is the global ContentAiChatDrawer; here just the FAB trigger.
    if (effectiveMode === "drawer") {
        return (
            <FloatingActionButton
                onPress={open}
                ariaLabel={t("contentAi.ask")}
                icon={SparkleIcon}
                classNames={classNames}
            />
        )
    }

    // RAIL — the resizable rail is rendered by the learn shell (rightRail) when open.
    // The FAB is the draggable toggle, hidden while the rail is open (the rail closes itself).
    if (isOpen) {
        return null
    }

    return (
        <div
            className={[
                "fixed right-[calc(var(--app-rail-w,0px)+1rem)] z-40 mb-[env(safe-area-inset-bottom)] touch-none",
                ...(classNames ?? []),
            ].join(" ")}
            style={{ bottom }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
        >
            <Button
                isIconOnly
                variant="primary"
                prefixIcon={SparkleIcon}
                ariaLabel={t("contentAi.ask")}
                onPress={onOpen}
                isElevated
            />
        </div>
    )
}

import React from "react"
import { Spinner } from "@/components/atoms/display/Spinner"
import { heroUiMdxComponents } from "../mdxComponents"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Compiled MDX module exposes its content as the default export. */
export type MdxContentComponent = React.ComponentType<{
    components?: Record<string, React.ElementType>
    className?: string
}>

/** Props for {@link _RenderReactComponent} — presentational; the compiled MDX component already resolved. */
export interface RenderReactComponentProps extends WithClassNames<undefined> {
    /** JSX/MDX source (shown verbatim on a compile error). */
    code: string
    /** The compiled MDX component, or `null` while compiling. */
    Content: MdxContentComponent | null
    /** `true` → the compile failed; falls back to showing `code` verbatim. */
    hasError: boolean
}

/**
 * Renders a ` ```mdx ` snippet as a REAL React tree — render ONLY, no tabs.
 *
 * Presentational: the connected half owns the (browser-only) `evaluate()`
 * compile, cached per-source via SWR; this component only picks the
 * error / loading / compiled branch. On a compile error the raw snippet is
 * shown verbatim (safe fallback) instead of crashing.
 * @param props - {@link RenderReactComponentProps}
 */
export const _RenderReactComponent = ({ code, Content, hasError, className }: RenderReactComponentProps) => {
    if (hasError) {
        return (
            <pre
                className={className
                    ? `not-prose overflow-auto rounded-xl border border-danger/40 bg-default/40 p-3 font-mono text-xs text-muted ${className}`
                    : "not-prose overflow-auto rounded-xl border border-danger/40 bg-default/40 p-3 font-mono text-xs text-muted"}
            >
                {code}
            </pre>
        )
    }
    if (!Content) {
        const spinner = <Spinner size="sm" label="Rendering" />
        return className ? <div className={className}>{spinner}</div> : spinner
    }
    return <Content components={heroUiMdxComponents} className={className} />
}

"use client"
import React, { PropsWithChildren } from "react"
import { useTranslations } from "next-intl"
import { useSelectedLayoutSegments, useSearchParams } from "next/navigation"
import { Spinner } from "@/components/atoms/display/Spinner"
import { _LearnShellLayout } from "./component"
import { ContentMap } from "@/components/blocks/learn/ContentMap"
import { MilestoneOutline } from "@/components/blocks/learn/MilestoneOutline"
import { LeaderboardCategoryRail } from "@/components/blocks/learn/LeaderboardCategoryRail"
import { OnThisPage } from "@/components/blocks/learn/OnThisPage"
import { ContentAiSelectionAsk } from "@/components/blocks/learn/ContentAiSelectionAsk"
import { EnrollGate } from "@/components/blocks/learn/EnrollGate"
import { PersonalProjectGatePreview } from "@/components/blocks/learn/personal-project/PersonalProjectGatePreview"
import { GithubLinkGate } from "@/components/blocks/auth/GithubLinkGate"
import { ResizableRail } from "@/components/blocks/layout/ResizableRail"
import { useQueryCourseSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseSwr"
import { useQueryCourseEnrollmentStatusSwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseEnrollmentStatusSwr"
import { useAppSelector } from "@/redux/hooks"

/**
 * Learn surfaces that require enrollment. Only the capstone (personal-project) is gated:
 * it's the enrolled-only hands-on outcome. Trial viewers ("Trial learn") may freely browse the
 * rest — flashcards (non-premium), leaderboard, foundations, content + mind-map — so those
 * are NOT gated. Keyed by `segments[0]`.
 */
const ENROLL_REQUIRED_SURFACES: ReadonlySet<string> = new Set([
    "personal-project",
])

/** i18n key for each gated surface's display name (folded into the gate title). */
const SURFACE_LABEL_KEY: Record<string, string> = {
    "personal-project": "finalProject.title",
}

/** Per-surface MOCK teaser rendered behind the enroll card (Medium-style gate). */
const SURFACE_PREVIEW: Record<string, React.ReactNode> = {
    "personal-project": <PersonalProjectGatePreview />,
}

export const LearnShellLayout = ({ children }: PropsWithChildren) => {
    const t = useTranslations()
    // load the active course here so EVERY learn tab has `course.entity` on a cold refresh
    // (the displayId is synced from the URL by a global effect). Tabs like personal-project
    // have no other loader, and downstream queries (milestones, etc.) gate on `course.id`.
    useQueryCourseSwr()
    // enrollment status drives the enroll-gate on hands-on surfaces (populates state.user.enrolled).
    const enrollmentSwr = useQueryCourseEnrollmentStatusSwr()
    const enrolled = useAppSelector((state) => state.user.enrolled)
    // `enrolled` defaults to false, so only trust it once the status query has settled —
    // otherwise an enrolled viewer would flash the gate on cold load.
    const enrollKnown = Boolean(enrollmentSwr.data) || Boolean(enrollmentSwr.error)
    // which learn sub-route is active. Docs-style layout:
    //  - "modules" (module list / detail / content) → content-map on the LEFT (persistent)
    //    + an on-this-page outline on the RIGHT (self-hides when the body has no headings).
    //  - "personal-project" → its milestone rail on the LEFT too (same place as the content-map),
    //    so the capstone reads like every other learn tab; no right rail.
    // every other tab (mind-map, foundations, headhuntings, practice, leaderboard, starci-ai)
    // has no side rails, so its content spans the full width.
    // lessons now live UNDER the content home (`/learn/content/modules/...`), so the
    // immediate child segment is "content" for BOTH the dashboard home and the reader.
    // Use the full segment list: `includes("modules")` flags the reader/module routes,
    // while `segments[0]` flags the top-level tabs (content / personal-project / mind-map).
    const segments = useSelectedLayoutSegments()
    const searchParams = useSearchParams()
    const isModules = segments.includes("modules")
    // the course-content home (`/learn/content`) + the lesson reader (`/content/modules/...`)
    // both share the content-map rail on the LEFT: the full module → lesson tree lives in
    // the rail (its one home), and the dashboard body shows continue + progress + the
    // current-module path instead of re-drawing the whole tree.
    const isContent = segments[0] === "content"
    const isPersonalProject = segments[0] === "personal-project"
    // the flashcards surface goes RAIL-LESS entirely (per concepts/when-rail: drop the 2nd rail
    // for the whole Review surface). The deck list lives IN the pane (study overview) and the
    // mode switch is in-pane on desktop too. `isFlashcards` only drives the mobile-bar choice.
    const isFlashcards = segments[0] === "flashcards"
    // the "Quick quiz" quiz goes full-bleed ONLY during a live run (a focused work
    // surface: its own `WorkSessionHeader` band IS the header) — detected off the
    // dedicated resumable route (`flashcards/quiz/sessions/[sessionId]`), same
    // pattern as the mock-interview's `isMockInterviewInterviewRoute` below.
    const isFlashcardQuizLive = isFlashcards && segments[1] === "quiz" && segments[2] === "sessions"
    // "Flashcard study"/"Due-card review" review goes full-bleed ONLY during a live session
    // — same idiom, detected off the dedicated resumable route
    // (`flashcards/review/sessions/[sessionId]`, 2026-07-11 clarification: "card review
    // same UI"). This ONE route now serves BOTH FlashcardReviewer
    // (single-deck) and DueReview (cross-deck) — the old deck-scoped route
    // (`review/decks/[deckId]/sessions/[sessionId]`) was consolidated away; the
    // bare `.../review` overview route (no `sessions` segment) is just the
    // resolve-only shim — stays centered, never full-bleed. Correction
    // 2026-07-12: the gate still checked the DELETED deck-scoped shape and
    // never matched the real route, so the shell kept applying its `p-6`
    // reading-column padding ON TOP of the surface's own full-bleed padding
    // (teacher: "drop padding-6 here", pointed at DevTools showing the shell's
    // `p-6 @max-app-lg:pb-16` wrapper still active on a live review session).
    const isFlashcardReviewLive = isFlashcards && segments[1] === "review" && segments[2] === "sessions"
    // the mind-map is a full-bleed interactive canvas (fills the viewport edge-to-edge),
    // so it opts out of the shell's canonical p-6 reading-column padding.
    const isMindMap = segments[0] === "mind-map"
    // the mock interview goes full-bleed ONLY during the live `interview` phase (a focused
    // work surface: conversation + tool workspace). setup/grading/scorecard stay centered.
    // The active phase is mirrored into the URL (`?phase=interview`) by MockInterviewSession
    // so the shell can drop the course rails + reading padding for that phase only.
    const isMockInterview = segments[0] === "mock-interview"
    // the dedicated resumable route (`mock-interview/interview/[sessionId]`) is
    // ALWAYS the live work surface — detected straight off the path segment so
    // there is no `?phase=interview` round-trip to wait on before the shell
    // drops its rails. Additive: the legacy `?phase=interview` query-param
    // mirror (still written by MockInterviewSession once mounted) keeps working
    // for the same route too.
    const isMockInterviewInterviewRoute = isMockInterview && segments[1] === "interview"
    const isMockInterviewLive = isMockInterviewInterviewRoute || (isMockInterview && searchParams.get("phase") === "interview")
    // a live quiz / interview grades a recruiter-facing signal → the AI chat is a
    // cheat channel there and gets suppressed (mirrors the same gate in InnerLayout,
    // which also kills a rail the learner left open before navigating in).
    const isAssessmentLive = isFlashcardQuizLive || isMockInterviewLive
    // ONLY the session (`…/playground/<slug>/session`) is a full-bleed work
    // surface (step guide + terminal/resources tabs), same reasoning as the live
    // mock-interview route. The exercise's SETUP page (`…/playground/<slug>`) and
    // the hub list (`…/playground`) are reading surfaces — install + pair
    // guidance, progress, machine status — so they keep the normal reading column.
    const isPlaygroundSession = segments[0] === "playground" && segments[2] === "session"
    // the leaderboard shows its XP-category selector as a sidebar (like the content
    // page) on the LEFT; the board reads the selection from the `?category=` URL param.
    const isLeaderboard = segments[0] === "leaderboard"
    // a single challenge (`…/contents/<id>/challenges/<id>`) KEEPS the course-tree rail (the
    // learner still navigates the course while solving), but its body is a tabbed single column
    // (Problem / Submit), so it needs no on-this-page outline. Only the right rail is dropped.
    const isChallenge = segments.includes("challenges")

    // persistent left rail (always visible on desktop): the width is drag-resizable
    // (persisted) via ResizableRail; sticky under the navbar and a flex column bounded to
    // the viewport so the rail pins its header/search and scrolls ONLY the list. Hidden
    // below lg (mobile opens it in the LearnMobileBar drawer).
    const railClass = "hidden shrink-0 @app-lg:flex @app-lg:flex-col @app-lg:sticky @app-lg:top-16 @app-lg:self-start @app-lg:h-[calc(100dvh-4rem)]"

    // left rail: course content-map while reading lessons AND on the content home;
    // milestone outline for the capstone.
    const leftRail = (isModules || isContent) ? (
        <ResizableRail
            className={railClass}
            storageKey="starci.learn.contentMap.width"
            defaultWidth={320}
            minWidth={256}
            maxWidth={560}
            ariaLabel={t("courseContents.resizeRail")}
        >
            <ContentMap className="min-h-0 @app-lg:flex-1" />
        </ResizableRail>
    ) : isPersonalProject ? (
        <ResizableRail
            className={railClass}
            storageKey="starci.learn.milestoneMap.width"
            defaultWidth={320}
            minWidth={256}
            maxWidth={560}
            ariaLabel={t("courseContents.resizeRail")}
        >
            <MilestoneOutline className="min-h-0 @app-lg:flex-1" />
        </ResizableRail>
    ) : isLeaderboard ? (
        <ResizableRail
            className={railClass}
            storageKey="starci.learn.leaderboardRail.width"
            defaultWidth={300}
            minWidth={240}
            maxWidth={420}
            ariaLabel={t("leaderboard.categories.label")}
        >
            <LeaderboardCategoryRail variant="rail" className="min-h-0 @app-lg:flex-1" />
        </ResizableRail>
    ) : undefined
    // right rail: on-this-page for the LESSON READER only (a real "contents/<id>" route) —
    // the module SHELL page (`/content/modules/<moduleId>`, no `contents` segment) is its own
    // dashboard (mirrors the course-content home, which also has no right rail) and would
    // otherwise inherit a stale TOC from whatever lesson was read last (OnThisPage self-hides
    // on `!contentId`, not on route — the module shell has no active content of its own).
    const isLessonReader = isModules && segments.includes("contents")
    const rightRail = (isLessonReader && !isChallenge) ? (
        <OnThisPage />
    ) : undefined

    // The content-AI chat rail is NOT a learn concern any more: it docks beside the
    // whole app from `InnerLayout`, so the learn right-rail slot is free to keep
    // serving the surface's own outline again.

    // enroll-gate: a trial viewer hitting a hands-on surface sees the enroll CTA, not a broken
    // page. Only gate once enrollment is KNOWN (enrolled defaults false → would flash otherwise);
    // while it resolves, hold the surface (and its enrollment-bound hooks) back behind a spinner.
    const surface = segments[0]
    const isEnrollRequired = Boolean(surface) && ENROLL_REQUIRED_SURFACES.has(surface as string)
    const showSurface = !isEnrollRequired || (enrollKnown && enrolled)
    const isGated = isEnrollRequired && enrollKnown && !enrolled
    const gateLabelKey = surface ? SURFACE_LABEL_KEY[surface] : undefined

    const content = showSurface
        ? children
        : isGated
            ? (
                <EnrollGate
                    title={t("enrollGate.title", { surface: gateLabelKey ? t(gateLabelKey) : "" })}
                    description={t("enrollGate.description")}
                    preview={surface ? SURFACE_PREVIEW[surface] : undefined}
                />
            )
            : (
                <div className="flex justify-center py-12">
                    <Spinner />
                </div>
            )

    return (
        <>
            {/* soft prompt: nudge learners with no linked GitHub to connect once per session */}
            <GithubLinkGate />
            {/* The floating "ask StarCi AI" mascot button now mounts ONCE, globally,
                from `InnerLayout` (app-wide chat, reachable outside a course too) —
                `InnerLayout` applies the same `isAssessmentLive` suppression during a
                live quiz / mock-interview (a course-grounded AI beside a
                recruiter-facing signal is a cheat channel). Chat returns after the
                session, on the scorecard, for "weak-tag review". */}
            {/* "ask AI about this passage" button on lesson-article text selection */}
            {!isAssessmentLive ? <ContentAiSelectionAsk /> : null}
            <_LearnShellLayout
                leftRail={showSurface ? leftRail : undefined}
                rightRail={showSurface ? rightRail : undefined}
                fullBleed={isMindMap || isMockInterviewLive || isPlaygroundSession || isFlashcardQuizLive || isFlashcardReviewLive}
                simpleMobileBar={isLeaderboard || isFlashcards}
            >
                {content}
            </_LearnShellLayout>
        </>
    )
}

"use client"

import React from "react"
import { Spinner } from "@/components/atoms/display/Spinner"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link LoadingScreen}. */
export type LoadingScreenProps = WithClassNames<undefined>

/**
 * Full-screen loading gate shown while the API key is being resolved.
 *
 * Presentational (render-only); "use client" because it relies on the house
 * Spinner atom (client).
 * @param props - optional className forwarded to the wrapper div
 */
export const LoadingScreen = ({
    className,
}: LoadingScreenProps = {}) => {
    return (
        <div
            className={className
                ? `min-h-screen bg-gradient-to-br from-slate-950 via-indigo-950 to-slate-900 flex items-center justify-center ${className}`
                : "min-h-screen bg-gradient-to-br from-slate-950 via-indigo-950 to-slate-900 flex items-center justify-center"}
        >
            <Spinner size="lg" />
        </div>
    )
}

import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import React from "react"
import {
    Spinner,
} from "@/components/atoms/display/Spinner"
import {
    UploadStatus,
} from "./enums"

/**
 * Status indicator rendered next to each provider row, keyed by upload state.
 *
 * Idle has no indicator (null); uploading shows a spinner; success/error show
 * their respective icons.
 */
export const UPLOAD_STATUS_ICON_MAP: Record<UploadStatus, React.ReactNode> = {
    [UploadStatus.Idle]: null,
    [UploadStatus.Uploading]: <Spinner size="sm" />,
    [UploadStatus.Success]: <CheckCircleIcon className="h-5 w-5 text-emerald-400" />,
    [UploadStatus.Error]: <XCircleIcon className="h-5 w-5 text-red-400" />,
}

/** Progress-bar track background class, keyed by upload state. */
export const UPLOAD_STATUS_TRACK_CLASS_MAP: Record<UploadStatus, string> = {
    [UploadStatus.Idle]: "bg-white/5",
    [UploadStatus.Uploading]: "bg-white/5",
    [UploadStatus.Success]: "bg-emerald-500/10",
    [UploadStatus.Error]: "bg-red-500/10",
}

/** Progress-bar fill background class, keyed by upload state. */
export const UPLOAD_STATUS_FILL_CLASS_MAP: Record<UploadStatus, string> = {
    [UploadStatus.Idle]: "bg-gradient-to-r from-indigo-500 to-purple-500",
    [UploadStatus.Uploading]: "bg-gradient-to-r from-indigo-500 to-purple-500",
    [UploadStatus.Success]: "bg-emerald-500",
    [UploadStatus.Error]: "bg-red-500",
}

import React from "react"
import {
    AsyncContentEmpty,
    AsyncContentError,
} from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import {
    CourseHero,
} from "./CourseHero"
import {
    CourseValueProps,
} from "./CourseValueProps"
import {
    CourseCurriculum,
} from "./CourseCurriculum"
import {
    CoursePrerequisites,
} from "./CoursePrerequisites"
import {
    CourseFaq,
} from "./CourseFaq"
import {
    CoursePricingRail,
} from "./CoursePricingRail"
import {
    CourseMobileEnrollBar,
} from "./CourseMobileEnrollBar"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Already-translated copy {@link _CourseDetailPage} needs — resolved by the connected `CourseDetailPage`. */
export interface CourseDetailLabels {
    /** Shown when the course fetch settles with no course to show. */
    notFound: string
    /** Shown when the course fetch settles with an error. */
    errorTitle: string
    /** Retry-button label on the error branch. */
    retry: string
}

/** Props for {@link _CourseDetailPage} — presentational; all data resolved, no fetch/store/i18n. */
export type CourseDetailPageProps = WithClassNames<undefined> & {
    /**
     * First load, nothing in hand → the spine mirrors itself in place (co-located). Owned by
     * the connected `CourseDetailPage` (first-load formula, `loading-and-skeleton.md` §2).
     */
    isSkeleton?: boolean
    /** Settled with no course → the not-found message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats a stale loading flag and the empty branch). */
    error?: unknown
    /** Retry handler paired with `labels.retry` on the error branch. */
    onRetry?: () => void
    /** Already-translated copy — see {@link CourseDetailLabels}. */
    labels: CourseDetailLabels
}

/**
 * Marketing-first course landing (UI 2.0) — the presentational half of {@link CourseDetailPage}: a
 * full-width hero (value + social proof + CTA above the fold), then a two-column body — narrative
 * on the left (what-you'll-learn → curriculum → before-you-start → FAQ) and a sticky pricing rail
 * on the right — plus a mobile sticky enroll bar. Replaces the legacy `layouts/course/Course`.
 *
 * `error` beats a stale loading flag; the not-found surface only shows once loading has settled
 * (`!isSkeleton && isEmpty`) — both are the shared `AsyncContentError`/`AsyncContentEmpty` frames,
 * never hand-written JSX (`loading-and-skeleton.md` §6). Every section below (`CourseHero`,
 * `CoursePricingRail`, `CourseValueProps`, `CourseCurriculum`, `CoursePrerequisites`, `CourseFaq`,
 * `CourseMobileEnrollBar`) is a self-fetching CONNECTED child — each reads the hydrated course from
 * redux itself (`tiers/split.md`: a presentational file may render a connected child) and takes no
 * `isSkeleton` prop of its own, so while shimmering this ONE tree mirrors their exact positions with
 * `Skeleton.*` right where each child sits instead (`loading-and-skeleton.md` §1's "no `isSkeleton`
 * prop → mirror minimally, co-located, not a parallel tree"). See `tiers/split.md` — the connected
 * `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link CourseDetailPageProps}
 */
const _CourseDetailPage = ({
    className,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    labels,
}: CourseDetailPageProps) => {
    if (error) {
        return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty title={labels.notFound} />
    }

    return (
        <Box
            identity={{ tier: "page", component: "CourseDetailPage" }}
            principle="center-measure"
            className={className
                ? `${className} mx-auto w-full max-w-6xl px-6 py-6 pb-24 @app-md:pb-6`
                : "mx-auto w-full max-w-6xl px-6 py-6 pb-24 @app-md:pb-6"}
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
        >
            {/* ONE grid from the top so the sticky purchase card's top lines up with the
                breadcrumb/header: header = row 1 (cols 1-2), card = col 3 spanning rows 1-2,
                narrative = row 2 (cols 1-2). Row gap = 10 (header → content, layouts/gap.md),
                column gap = 6. DOM order hero → card → narrative → mobile stacks
                header → purchase card → curriculum. */}
            <>
                <div className="grid grid-cols-1 items-start gap-x-6 gap-y-10 @app-md:grid-cols-3">
                    {isSkeleton ? (
                        <Box className="@app-md:col-span-2 @app-md:col-start-1 @app-md:row-start-1">
                            <StackV gap={4} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." items={[
                                    () => <Skeleton.Typography type="h2" />,
                                    () => <Skeleton.Typography type="body" />,
                                    () => <Skeleton.Metric />,
                                ]} />
                        </Box>
                    ) : (
                        <CourseHero className="@app-md:col-span-2 @app-md:col-start-1 @app-md:row-start-1" />
                    )}
                    {isSkeleton ? (
                        <Skeleton.Card className="@app-md:col-span-1 @app-md:col-start-3 @app-md:row-span-2 @app-md:row-start-1" />
                    ) : (
                        <CoursePricingRail className="@app-md:col-span-1 @app-md:col-start-3 @app-md:row-span-2 @app-md:row-start-1" />
                    )}
                    {isSkeleton ? (
                        <Skeleton.Accordion items={3} className="@app-md:col-span-2 @app-md:col-start-1 @app-md:row-start-2" />
                    ) : (
                        <Box className="@app-md:col-span-2 @app-md:col-start-1 @app-md:row-start-2">
                            <StackV gap={6} principle="block-boundary"
                                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups." items={[
                                    CourseValueProps,
                                    CourseCurriculum,
                                    CoursePrerequisites,
                                    CourseFaq,
                                ]} />
                        </Box>
                    )}
                </div>
                {/* mobile-only sticky enroll bar — reads course/price itself, so it only
                    renders once the real spine has loaded (matches the old AsyncContent
                    content branch, which never rendered it during loading either). */}
                {!isSkeleton && <CourseMobileEnrollBar className="@app-md:hidden" />}
            </>
        </Box>
    )
}

export { _CourseDetailPage }

"use client"

import React, {
    Suspense,
    useCallback,
    useEffect,
    useState,
} from "react"
import {
    Spinner,
} from "@/components/atoms/display/Spinner"
import {
    useLocale,
} from "next-intl"
import {
    useSearchParams,
} from "next/navigation"
import {
    useQueryCourseEnrollmentStatusSwr,
} from "@/hooks/swr/api/graphql/queries/useQueryCourseEnrollmentStatusSwr"
import {
    useRouter,
} from "@/i18n/navigation"
import {
    EnrolledSuccess,
} from "./EnrolledSuccess"
import {
    CheckoutExpired,
} from "./CheckoutExpired"
import {
    QrPanel,
} from "./QrPanel"
import {
    OrderSummary,
} from "./OrderSummary"
import { pathConfig } from "@/resources/path"
import { Box } from "@/components/frames/Box"
import { Grid } from "@/components/frames/Grid"

/** How often (ms) to re-poll the enrollment status while waiting for payment. */
const POLL_INTERVAL_MS = 5000
/** Delay (ms) before redirecting to the course once enrollment is confirmed. */
const REDIRECT_DELAY_MS = 2000
/**
 * How long (ms) to keep polling before treating the checkout as timed out.
 * There is no transaction-status query in the FE GraphQL layer (the only signal
 * is enrollment, which can never flip `true → false`), so once this window
 * elapses without enrollment we surface a terminal "expired" state rather than
 * spinning forever — matching the BE's `Pending → Unpaid` transition
 * (`transactions/business.md`). 15 minutes covers a slow bank transfer.
 */
const CHECKOUT_EXPIRY_MS = 15 * 60 * 1000

/**
 * SePay checkout container.
 *
 * Owns only the page-level concern: poll the course enrollment status via SWR
 * and redirect to the course once enrollment lands (showing the success screen
 * for a beat first). Each panel is self-contained — `QrPanel` and `OrderSummary`
 * read their own query params and own their own handlers — so this container
 * just composes them. `"use client"` because it runs effects + reads params.
 */
const SepayCheckoutPageContent = () => {
    const searchParams = useSearchParams()
    const locale = useLocale()
    const router = useRouter()

    const courseId = searchParams.get("courseId") || ""

    const {
        data: statusData,
        mutate: refreshStatus,
    } = useQueryCourseEnrollmentStatusSwr()
    const isEnrolled = statusData?.courseEnrollmentStatus?.data?.isEnrolled

    // once the checkout window elapses without enrollment, flip to the terminal
    // "expired" state (there is no tx-status query to observe `Unpaid` directly)
    const [isExpired, setIsExpired] = useState(false)

    // poll the enrollment status on a fixed interval while waiting for payment —
    // stops once we're enrolled (redirecting) or the checkout has expired, so we
    // don't keep hitting the API on a settled/dead checkout
    useEffect(
        () => {
            if (isEnrolled || isExpired) {
                return
            }
            const interval = setInterval(
                () => {
                    refreshStatus()
                },
                POLL_INTERVAL_MS,
            )
            return () => clearInterval(interval)
        },
        [
            refreshStatus,
            isEnrolled,
            isExpired,
        ],
    )

    // arm the expiry timeout while waiting; re-arms whenever the user re-checks
    // (which resets `isExpired` to false), and never fires once enrolled
    useEffect(
        () => {
            if (isEnrolled || isExpired) {
                return
            }
            const timer = setTimeout(
                () => {
                    setIsExpired(true)
                },
                CHECKOUT_EXPIRY_MS,
            )
            return () => clearTimeout(timer)
        },
        [
            isEnrolled,
            isExpired,
        ],
    )

    // re-open the poll window and re-check once more (e.g. a slow transfer just
    // settled after the timeout) — resets the terminal back to the waiting view
    const onRecheck = useCallback(
        () => {
            setIsExpired(false)
            refreshStatus()
        },
        [
            refreshStatus,
        ],
    )

    // once enrolled, give the success screen a beat then redirect to the course
    useEffect(
        () => {
            if (isEnrolled) {
                const timer = setTimeout(
                    () => {
                        router.push(pathConfig().locale(locale).course(courseId).build())
                    },
                    REDIRECT_DELAY_MS,
                )
                return () => clearTimeout(timer)
            }
        },
        [
            isEnrolled,
            courseId,
            locale,
            router,
        ],
    )

    if (isEnrolled) {
        return <EnrolledSuccess />
    }

    if (isExpired) {
        return <CheckoutExpired onRecheck={onRecheck} />
    }

    return (
        <Box principle="page-pad" className="flex min-h-screen flex-col items-center px-4 py-12"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
            <Box principle="center-measure" className="w-full max-w-4xl"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                <Grid
                    columns={{ base: 1, md: 2 }}
                    principle="layout-split"

                    explain="Major layout split — not block-boundary, because this separates primary page regions rather than adjacent blocks."
                    items={[
                        { key: "qr", content: QrPanel },
                        { key: "summary", content: OrderSummary },
                    ]}
                />
            </Box>
        </Box>
    )
}

/**
 * Public SePay checkout entry point.
 *
 * Wraps {@link SepayCheckoutPageContent} in a Suspense boundary (required because
 * the content + panels read `useSearchParams`) with a centered spinner fallback.
 * Mounted by the `/[locale]/checkout/sepay` route.
 */
export const SepayCheckoutPage = () => {
    return (
        <Suspense
            fallback={
                <div className="flex min-h-[80vh] items-center justify-center">
                    <Spinner size="lg" />
                </div>
            }
        >
            <SepayCheckoutPageContent />
        </Suspense>
    )
}
